using System;
using System.IO;
using System.Drawing;
using System.Media;
using System.Threading.Tasks;
using System.Windows.Forms;

sealed class CallHistoryDetails:Form {
 readonly CallHistoryRow row;readonly string root;readonly ListBox recordings=new ListBox();readonly TextBox log=new TextBox();readonly Label hint=DeckTheme.Label("",10,DeckTheme.Dim);readonly DeckButton play=new DeckButton(),stop=new DeckButton(),folder=new DeckButton();SoundPlayer player;string commandLog="";bool loaded;
 public CallHistoryDetails(CallHistoryRow entry,string storage){
  row=entry;root=storage;Text=UiPreferences.T("PhoneDeck · Registro da chamada","PhoneDeck · Call record");Name="CallHistoryDetails";ClientSize=new Size(900,700);MinimumSize=new Size(720,580);StartPosition=FormStartPosition.CenterParent;BackColor=DeckTheme.Bg;ForeColor=DeckTheme.Text;Font=new Font("Segoe UI",10);
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=6};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,30));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));Controls.Add(layout);
  string contact=String.IsNullOrWhiteSpace(row.Contact)?UiPreferences.T("Não identificado","Unknown"):row.Contact;
  var header=DeckTheme.Label(contact+Environment.NewLine+UiPreferences.T("Número solicitado: ","Requested number: ")+(String.IsNullOrEmpty(row.Number)?"—":row.Number)+Environment.NewLine+UiPreferences.T("Comando em: ","Command at: ")+row.RequestedAt.ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss zzz")+Environment.NewLine+UiPreferences.T("Horário UTC: ","UTC time: ")+row.RequestedAt.UtcDateTime.ToString("yyyy-MM-dd HH:mm:ss 'UTC'"),11,DeckTheme.Text,true);header.Dock=DockStyle.Fill;layout.Controls.Add(header,0,0);
  hint.Text=UiPreferences.T("Carregando gravações e log…","Loading recordings and log…");hint.Dock=DockStyle.Fill;layout.Controls.Add(hint,0,1);
  recordings.Name="CallRecordings";recordings.Dock=DockStyle.Fill;recordings.BackColor=DeckTheme.Surface;recordings.ForeColor=DeckTheme.Text;recordings.BorderStyle=BorderStyle.None;recordings.SelectedIndexChanged+=(s,e)=>SelectRecording();layout.Controls.Add(recordings,0,2);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};Setup(play,UiPreferences.T("Ouvir gravação","Play recording"),DeckTheme.Green);Setup(stop,UiPreferences.T("Parar áudio","Stop audio"),DeckTheme.Raised);Setup(folder,UiPreferences.T("Abrir pasta","Open folder"),DeckTheme.Raised);actions.Controls.AddRange(new Control[]{play,stop,folder});layout.Controls.Add(actions,0,3);
  play.Click+=(s,e)=>Play();stop.Click+=(s,e)=>StopAudio();folder.Click+=(s,e)=>{try{var selected=recordings.SelectedItem as CallRecordingInfo;System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(selected==null?Path.GetDirectoryName(row.Journal):selected.Folder){UseShellExecute=true});}catch(Exception ex){hint.Text=ex.Message;}};
  log.Name="CallEvidenceLog";log.Multiline=true;log.ReadOnly=true;log.ScrollBars=ScrollBars.Both;log.WordWrap=false;log.Dock=DockStyle.Fill;log.BackColor=DeckTheme.Surface;log.ForeColor=DeckTheme.Text;log.BorderStyle=BorderStyle.None;log.Font=new Font("Consolas",10);layout.Controls.Add(log,0,4);
  var note=DeckTheme.Label(UiPreferences.T("Associação pelo registro local; identidade e horário externo não certificados.","Associated by local record; identity and external time are not certified."),8,DeckTheme.Dim);note.Dock=DockStyle.Fill;layout.Controls.Add(note,0,5);
  play.Enabled=false;stop.Enabled=false;folder.Enabled=false;Shown+=async(s,e)=>await LoadRecords();FormClosed+=(s,e)=>StopAudio();UiPreferences.Apply(this);
 }
 static void Setup(DeckButton button,string text,Color color){button.Text=text;button.Fill=color;button.Size=new Size(155,34);button.Margin=new Padding(0,3,8,0);}
 public async Task LoadRecords(){if(loaded)return;loaded=true;try{var data=await Task.Run(()=>{commandLog=CallRecordingLookup.ReadLog(row.Journal);return CallRecordingLookup.Find(root,row);});if(IsDisposed)return;foreach(var item in data)recordings.Items.Add(item);folder.Enabled=File.Exists(row.Journal);if(data.Count>0)recordings.SelectedIndex=0;else{hint.Text=UiPreferences.T("Sem gravação associada. Log da chamada disponível abaixo.","No associated recording. Call log is available below.");log.Text=commandLog;}}catch(Exception e){if(!IsDisposed)hint.Text=e.Message;}}
 void SelectRecording(){StopAudio();var item=recordings.SelectedItem as CallRecordingInfo;if(item==null)return;hint.Text=!item.Integrity?UiPreferences.T("Pacote incompleto ou alterado; reprodução bloqueada.","Incomplete or changed bundle; playback blocked."):item.State=="partial"?UiPreferences.T("Gravação parcial · integridade local conferida.","Partial recording · local integrity checked."):UiPreferences.T("Gravação associada · integridade local conferida.","Associated recording · local integrity checked.");play.Enabled=item.Integrity&&File.Exists(Path.Combine(item.Folder,"conversa.wav"));folder.Enabled=true;log.Text=item.Summary+Environment.NewLine+"──────── LOG DA CHAMADA ────────"+Environment.NewLine+commandLog+Environment.NewLine+"──────── LOG DA GRAVAÇÃO ────────"+Environment.NewLine+CallRecordingLookup.ReadLog(Path.Combine(item.Folder,"eventos.jsonl"));}
 async void Play(){var item=recordings.SelectedItem as CallRecordingInfo;if(item==null)return;play.Enabled=false;try{bool valid=await Task.Run(()=>EvidenceJournal.VerifyBundle(item.Folder));if(IsDisposed||recordings.SelectedItem!=item)return;if(!valid){hint.Text=UiPreferences.T("A integridade mudou; reprodução bloqueada.","Integrity changed; playback blocked.");return;}StopAudio();player=new SoundPlayer(Path.Combine(item.Folder,"conversa.wav"));player.Play();stop.Enabled=true;}catch(Exception e){if(!IsDisposed)hint.Text=e.Message;}finally{if(!IsDisposed)play.Enabled=true;}}
 void StopAudio(){if(player!=null){player.Stop();player.Dispose();player=null;}stop.Enabled=false;}
}